"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7650],{54487:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TechTreeGuiController","desc":"Drives `StarterGui.TechTreeGui`. Studio holds the panel plus one template\\nper repeated piece (the `Templates` folder). This controller clones a tab\\nper `ResearchConfig.Branches` entry and, for the open branch, a card per\\nnode, a connector Frame per line segment and a tier label per row, all\\nplaced by `TechTreeGuiRules` from each node\'s `Tier`, `Column` and\\n`Prereqs`. Adding a node or a branch is a config edit. Refuel is hold to\\ncharge, pay on release: one `ReqResearchRefuel(points)` per hold.","realm":["Client"],"source":{"line":14,"path":"src/StarterPlayer/StarterPlayerScripts/TechTreeGuiController.client.luau"}}')}}]);